          layout
          transition={{ type: 'spring', stiffness: 500, damping: 30 }}
          animate={{ x: isChecked ? dimensions.travel : 0 }}
          className={cn(
            'pointer-events-none block rounded-full bg-card shadow-sm border border-border/50 tactile-surface',
            dimensions.thumb
          )}
        />
      </button>
    );
  }
);

