'use client';

import * as React from 'react';
import { motion } from 'framer-motion';
import { cn } from '@/lib/utils';

export interface SparklineProps extends React.SVGAttributes<SVGSVGElement> {
  data: number[];
  width?: number;
  height?: number;
  strokeWidth?: number;
  color?: string;
  showGradient?: boolean;
  showEndDot?: boolean;
}

export function Sparkline({
  data,
  width = 120,
  height = 38,
  strokeWidth = 1.75,
  color = 'var(--text-primary)',
  showGradient = true,
  showEndDot = true,
  className,
  ...props
}: SparklineProps) {
  const rawId = React.useId();
  const id = rawId.replace(/[^a-zA-Z0-9]/g, '');
  const gradientId = `sparkline-gradient-${id}`;

  if (!data || data.length < 2) {
    return (
      <div
        className="h-9 rounded-md bg-secondary/30 animate-pulse border border-border/40"
        style={{ width }}
      />
    );
  }

  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min === 0 ? 1 : max - min;
  const paddingY = 5;
  const usableHeight = height - paddingY * 2;

  const points = data.map((val, idx) => {
    const x = (idx / (data.length - 1)) * width;
    const y = height - paddingY - ((val - min) / range) * usableHeight;
    return { x, y };
  });

  // Generate smooth cubic Bézier SVG path with natural tension
  let pathD = `M ${points[0].x},${points[0].y}`;
  for (let i = 0; i < points.length - 1; i++) {
    const curr = points[i];
    const next = points[i + 1];
    const cpX1 = curr.x + (next.x - curr.x) / 2;
    const cpY1 = curr.y;
    const cpX2 = curr.x + (next.x - curr.x) / 2;
    const cpY2 = next.y;
    pathD += ` C ${cpX1},${cpY1} ${cpX2},${cpY2} ${next.x},${next.y}`;
  }

  const areaD = `${pathD} L ${points[points.length - 1].x},${height} L ${points[0].x},${height} Z`;
  const lastPoint = points[points.length - 1];

  return (
    <svg
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      className={cn('overflow-visible select-none block', className)}
      {...props}
    >
      <defs>
        <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={color} stopOpacity="0.12" />
          <stop offset="100%" stopColor={color} stopOpacity="0.0" />
        </linearGradient>
      </defs>

      {/* Atmospheric Area Gradient Fill */}
      {showGradient && (
        <path d={areaD} fill={`url(#${gradientId})`} className="pointer-events-none" />
      )}

      {/* Smooth Trajectory Path */}
      <motion.path
        d={pathD}
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        className="opacity-90"
        initial={{ pathLength: 0 }}
        animate={{ pathLength: 1 }}
        transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
      />

      {/* Precision Terminal Dot */}
      {showEndDot && (
        <g>
          <circle
            cx={lastPoint.x}
            cy={lastPoint.y}
            r="5"
            fill={color}
            className="opacity-15"
          />
          <circle
            cx={lastPoint.x}
            cy={lastPoint.y}
            r="2.5"
            fill="var(--card)"
            stroke={color}
            strokeWidth="1.5"
            className="drop-shadow-xs"
          />
        </g>
      )}
    </svg>
  );
}

'use client';

import * as React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '@/lib/utils';

export interface AreaChartDataPoint {
  label: string;
  value: number;
  baseline?: number;
  formattedValue?: string;
}

export interface AreaChartProps extends React.HTMLAttributes<HTMLDivElement> {
  data: AreaChartDataPoint[];
  height?: number;
  color?: string;
  showGrid?: boolean;
  showAxes?: boolean;
  unit?: string;
  curveTension?: number;
}

export function AreaChart({
  data,
  height = 240,
  color = 'var(--text-primary)',
  showGrid = true,
  showAxes = true,
  unit = '',
  curveTension = 0.35,
  className,
  ...props
}: AreaChartProps) {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const [width, setWidth] = React.useState(0);
  const [hoveredIndex, setHoveredIndex] = React.useState<number | null>(null);

  const rawId = React.useId();
  const id = rawId.replace(/[^a-zA-Z0-9]/g, '');
  const gradientId = `areachart-gradient-${id}`;
  const glowId = `areachart-glow-${id}`;

  React.useEffect(() => {
    if (!containerRef.current) return;
    const updateWidth = () => {
      if (containerRef.current) {
        const clientW = containerRef.current.clientWidth;
        if (clientW > 0) setWidth(clientW);
      }
    };
    updateWidth();
    const observer = new ResizeObserver((entries) => {
      if (entries[0] && entries[0].contentRect.width > 0) {
        setWidth(entries[0].contentRect.width);
      }
    });
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  if (!data || data.length < 2) {
    return (
      <div
        ref={containerRef}
        style={{ height }}
        className="w-full flex items-center justify-center rounded-[20px] bg-card border border-border/60 text-xs font-mono text-text-muted"
      >
        Insufficient telemetry data
      </div>
    );
  }

  const effectiveWidth = width > 0 ? width : 600;

  const paddingLeft = showAxes ? 56 : 16;
  const paddingRight = 24;
  const paddingTop = 32;
  const paddingBottom = showAxes ? 38 : 16;

  const chartWidth = Math.max(10, effectiveWidth - paddingLeft - paddingRight);
  const chartHeight = Math.max(10, height - paddingTop - paddingBottom);

  const values = data.map((d) => d.value);
  const minVal = Math.min(...values) * 0.95;
  const maxVal = Math.max(...values) * 1.05;
  const range = maxVal - minVal || 1;

  const points = data.map((item, idx) => {
    const x = paddingLeft + (idx / (data.length - 1)) * chartWidth;
    const y = paddingTop + chartHeight - ((item.value - minVal) / range) * chartHeight;
    return { x, y, item, idx };
  });

  // Smooth Catmull-Rom cubic spline path
  const buildSmoothPath = (pts: typeof points) => {
    let path = `M ${pts[0].x},${pts[0].y}`;
    for (let i = 0; i < pts.length - 1; i++) {
      const p0 = i > 0 ? pts[i - 1] : pts[0];
      const p1 = pts[i];
      const p2 = pts[i + 1];
      const p3 = i !== pts.length - 2 ? pts[i + 2] : p2;

      const cp1x = p1.x + ((p2.x - p0.x) / 6) * curveTension * 2;
      const cp1y = p1.y + ((p2.y - p0.y) / 6) * curveTension * 2;
      const cp2x = p2.x - ((p3.x - p1.x) / 6) * curveTension * 2;
      const cp2y = p2.y - ((p3.y - p1.y) / 6) * curveTension * 2;

      path += ` C ${cp1x},${cp1y} ${cp2x},${cp2y} ${p2.x},${p2.y}`;
    }
    return path;
  };

  const linePath = buildSmoothPath(points);
  const baselineY = paddingTop + chartHeight;
  const areaPath = `${linePath} L ${points[points.length - 1].x},${baselineY} L ${points[0].x},${baselineY} Z`;

  const gridTiers = [0, 0.5, 1];
  const hoveredPoint = hoveredIndex !== null ? points[hoveredIndex] : null;

  return (
    <div
      ref={containerRef}
      className={cn(
        'relative w-full max-w-full rounded-[24px] border border-border/70 bg-card select-none shadow-tactile transition-colors overflow-hidden',
        className
      )}
      style={{ height, minHeight: height }}
      onMouseLeave={() => setHoveredIndex(null)}
      {...props}
    >
      {/* Precision Floating Tooltip Pill */}
      <AnimatePresence>
        {hoveredPoint && (
          <motion.div
            initial={{ opacity: 0, y: 2, scale: 0.97 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, scale: 0.97 }}
            transition={{ duration: 0.15, ease: [0.16, 1, 0.3, 1] }}
            className="absolute top-3 right-4 z-20 px-3 py-1.5 rounded-xl bg-card/95 backdrop-blur-md border border-border/90 text-xs font-mono text-text-primary shadow-tactile pointer-events-none flex items-center gap-2 max-w-[calc(100%-32px)] truncate"
          >
            <span className="w-1.5 h-1.5 rounded-full bg-primary shrink-0" />
            <span className="text-text-muted shrink-0">{hoveredPoint.item.label}:</span>
            <span className="font-semibold text-text-primary shrink-0">
              {hoveredPoint.item.formattedValue || `${hoveredPoint.item.value.toLocaleString()}${unit}`}
            </span>
          </motion.div>
        )}
      </AnimatePresence>

      <svg
        width="100%"
        height={height}
        viewBox={`0 0 ${effectiveWidth} ${height}`}
        className="block overflow-hidden max-w-full"
        style={{ width: '100%', height: `${height}px` }}
      >
        <defs>
          <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={color} stopOpacity="0.22" />
            <stop offset="60%" stopColor={color} stopOpacity="0.05" />
            <stop offset="100%" stopColor={color} stopOpacity="0.0" />
          </linearGradient>
          <filter id={glowId} x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="3" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>

        {/* Horizontal Dashed Gridlines */}
        {showGrid &&
          gridTiers.map((tier, idx) => {
            const y = paddingTop + chartHeight * (1 - tier);
            const val = minVal + tier * range;
            return (
              <g key={idx}>
                <line
                  x1={paddingLeft}
                  y1={y}
                  x2={chartWidth + paddingLeft}
                  y2={y}
                  stroke="var(--border)"
                  strokeDasharray="3 3"
                  strokeWidth="0.75"
                  className="opacity-50"
                />
                {showAxes && (
                  <text
                    x={paddingLeft - 10}
                    y={y + 3.5}
                    textAnchor="end"
                    className="text-[10px] font-mono fill-text-muted/60 select-none"
                  >
                    {Math.round(val).toLocaleString()}{unit}
                  </text>
                )}
              </g>
            );
          })}

        {/* Ambient Area Gradient Fill */}
        <path d={areaPath} fill={`url(#${gradientId})`} className="pointer-events-none" />

        {/* Ambient Glow Halo behind line */}
        <path
          d={linePath}
          fill="none"
          stroke={color}
          strokeWidth="4"
          strokeLinecap="round"
          strokeLinejoin="round"
          className="opacity-15 pointer-events-none"
          filter={`url(#${glowId})`}
        />

        {/* Spline Wave Line */}
        <motion.path
          d={linePath}
          fill="none"
          stroke={color}
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          className="opacity-95 pointer-events-none"
          initial={{ pathLength: 0 }}
          animate={{ pathLength: 1 }}
          transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
        />

        {/* Hover Crosshair & Indicator Point */}
        {hoveredPoint && (
          <g className="pointer-events-none">
            {/* Scrubber vertical line */}
            <line
              x1={hoveredPoint.x}
              y1={paddingTop}
              x2={hoveredPoint.x}
              y2={baselineY}
              stroke={color}
              strokeDasharray="2 3"
              strokeWidth="1"
              className="opacity-60"
            />
            {/* Outer ambient pulse ring */}
            <circle
              cx={hoveredPoint.x}
              cy={hoveredPoint.y}
              r="8"
              fill={color}
              className="opacity-20 animate-pulse"
            />
            {/* Inner specular dot */}
            <circle
              cx={hoveredPoint.x}
              cy={hoveredPoint.y}
              r="4"
              fill="var(--card)"
              stroke={color}
              strokeWidth="2"
              className="drop-shadow-xs"
            />
          </g>
        )}

        {/* Interactive Scrub Slices */}
        {points.map((pt, idx) => {
          const sliceWidth = chartWidth / points.length;
          const sliceX = pt.x - sliceWidth / 2;

          return (
            <g key={idx}>
              <rect
                x={sliceX}
                y={0}
                width={sliceWidth}
                height={height}
                fill="transparent"
                className="cursor-pointer"
                onMouseEnter={() => setHoveredIndex(idx)}
              />

              {showAxes && (
                <text
                  x={pt.x}
                  y={baselineY + 20}
                  textAnchor="middle"
                  className={cn(
                    'text-[10.5px] font-mono transition-colors select-none',
                    hoveredIndex === idx ? 'fill-text-primary font-medium' : 'fill-text-muted/60'
                  )}
                >
                  {pt.item.label}
                </text>
              )}
            </g>
          );
        })}
      </svg>
    </div>
  );
}

'use client';

import * as React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '@/lib/utils';

export interface BarChartDataPoint {
  label: string;
  value: number;
  secondaryValue?: number;
  formattedValue?: string;
}

export interface BarChartProps extends React.HTMLAttributes<HTMLDivElement> {
  data: BarChartDataPoint[];
  height?: number;
  barColor?: string;
  showGrid?: boolean;
  showAxes?: boolean;
  unit?: string;
}

export function BarChart({
  data,
  height = 240,
  barColor = 'var(--text-primary)',
  showGrid = true,
  showAxes = true,
  unit = '',
  className,
  ...props
}: BarChartProps) {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const [width, setWidth] = React.useState(0);
  const [hoveredIndex, setHoveredIndex] = React.useState<number | null>(null);

  React.useEffect(() => {
    if (!containerRef.current) return;
    const updateWidth = () => {
      if (containerRef.current) {
        const clientW = containerRef.current.clientWidth;
        if (clientW > 0) setWidth(clientW);
      }
    };
    updateWidth();
    const observer = new ResizeObserver((entries) => {
      if (entries[0] && entries[0].contentRect.width > 0) {
        setWidth(entries[0].contentRect.width);
      }
    });
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  if (!data || data.length === 0) {
    return (
      <div
        ref={containerRef}
        style={{ height }}
        className="w-full flex items-center justify-center rounded-[20px] bg-card border border-border/60 text-xs font-mono text-text-muted"
      >
        No telemetry data available
      </div>
    );
  }

  const effectiveWidth = width > 0 ? width : 600;

  const paddingLeft = showAxes ? 56 : 16;
  const paddingRight = 24;
  const paddingTop = 32;
  const paddingBottom = showAxes ? 38 : 16;

  const chartWidth = Math.max(10, effectiveWidth - paddingLeft - paddingRight);
  const chartHeight = Math.max(10, height - paddingTop - paddingBottom);

  const maxVal = Math.max(...data.map((d) => d.value), 1) * 1.08;
  const barSlotWidth = chartWidth / data.length;
  const barWidth = Math.min(32, Math.max(10, barSlotWidth * 0.44));

  const gridTiers = [0, 0.5, 1];
  const hoveredItem = hoveredIndex !== null ? data[hoveredIndex] : null;

  return (
    <div
      ref={containerRef}
      className={cn(
        'relative w-full max-w-full rounded-[24px] border border-border/70 bg-card select-none shadow-tactile transition-colors overflow-hidden',
        className
      )}
      style={{ height, minHeight: height }}
      onMouseLeave={() => setHoveredIndex(null)}
      {...props}
    >
      {/* Floating Hover Readout Pill */}
      <AnimatePresence>
        {hoveredItem && hoveredIndex !== null && (
          <motion.div
            initial={{ opacity: 0, y: 2, scale: 0.97 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, scale: 0.97 }}
            transition={{ duration: 0.15, ease: [0.16, 1, 0.3, 1] }}
            className="absolute top-3 right-4 z-20 px-3 py-1.5 rounded-xl bg-card/95 backdrop-blur-md border border-border/90 text-xs font-mono text-text-primary shadow-tactile pointer-events-none flex items-center gap-2 max-w-[calc(100%-32px)] truncate"
          >
            <span className="w-1.5 h-1.5 rounded-full bg-primary shrink-0" />
            <span className="text-text-muted shrink-0">{hoveredItem.label}:</span>
            <span className="font-semibold text-text-primary shrink-0">
              {hoveredItem.formattedValue || `${hoveredItem.value.toLocaleString()}${unit}`}
            </span>
            {hoveredItem.secondaryValue !== undefined && (
              <span className="text-[10px] text-text-muted shrink-0">
                (prev {hoveredItem.secondaryValue.toLocaleString()}{unit})
              </span>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      <svg
        width="100%"
        height={height}
        viewBox={`0 0 ${effectiveWidth} ${height}`}
        className="block overflow-hidden max-w-full"
        style={{ width: '100%', height: `${height}px` }}
      >
        {/* Horizontal Dashed Gridlines */}
        {showGrid &&
          gridTiers.map((tier, idx) => {
            const y = paddingTop + chartHeight * (1 - tier);
            return (
              <g key={idx}>
                <line
                  x1={paddingLeft}
                  y1={y}
                  x2={chartWidth + paddingLeft}
                  y2={y}
                  stroke="var(--border)"
                  strokeDasharray="3 3"
                  strokeWidth="0.75"
                  className="opacity-50"
                />
                {showAxes && (
                  <text
                    x={paddingLeft - 10}
                    y={y + 3.5}
                    textAnchor="end"
                    className="text-[10px] font-mono fill-text-muted/60 select-none"
                  >
                    {Math.round(tier * maxVal).toLocaleString()}{unit}
                  </text>
                )}
              </g>
            );
          })}

        {/* Tactile Bar Columns */}
        {data.map((item, idx) => {
          const barHeight = Math.max(2, (item.value / maxVal) * chartHeight);
          const x = paddingLeft + idx * barSlotWidth + (barSlotWidth - barWidth) / 2;
          const y = paddingTop + chartHeight - barHeight;
          const isHovered = hoveredIndex === idx;

          const maxChars = Math.max(3, Math.floor(barSlotWidth / 7.5));
          const labelText =
            item.label.length > maxChars
              ? `${item.label.slice(0, Math.max(1, maxChars - 1))}…`
              : item.label;

          return (
            <g key={idx}>
              {/* Vertical Spotlight Beam on Hover */}
              {isHovered && (
                <rect
                  x={paddingLeft + idx * barSlotWidth + 2}
                  y={paddingTop}
                  width={barSlotWidth - 4}
                  height={chartHeight}
                  rx={8}
                  fill="var(--text-primary)"
                  className="opacity-[0.03] pointer-events-none transition-opacity duration-200"
                />
              )}

              {/* Recessed Track Well */}
              <rect
                x={x}
                y={paddingTop}
                width={barWidth}
                height={chartHeight}
                rx={5}
                fill="var(--secondary)"
                className="opacity-30 pointer-events-none"
              />

              {/* Filled Tactile Bar */}
              <motion.rect
                x={x}
                y={y}
                width={barWidth}
                height={barHeight}
                rx={5}
                fill={barColor}
                className={cn(
                  'transition-colors duration-200 pointer-events-none drop-shadow-xs',
                  isHovered ? 'opacity-100 brightness-110' : 'opacity-85'
                )}
                initial={{ height: 0, y: paddingTop + chartHeight }}
                animate={{ height: barHeight, y }}
                transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
              />

              {/* Top Hairline Specular Edge */}
              <motion.line
                x1={x + 2}
                y1={y}
                x2={x + barWidth - 2}
                y2={y}
                stroke="#ffffff"
                strokeWidth="1.25"
                className="opacity-40 pointer-events-none"
                initial={{ opacity: 0, y1: paddingTop + chartHeight, y2: paddingTop + chartHeight }}
                animate={{ opacity: 0.4, y1: y, y2: y }}
                transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
              />

              {/* Interactive Hit Area */}
              <rect
                x={paddingLeft + idx * barSlotWidth}
                y={0}
                width={barSlotWidth}
                height={height}
                fill="transparent"
                className="cursor-pointer"
                onMouseEnter={() => setHoveredIndex(idx)}
              />

              {/* X-Axis Category Label */}
              {showAxes && (
                <text
                  x={x + barWidth / 2}
                  y={paddingTop + chartHeight + 20}
                  textAnchor="middle"
                  className={cn(
                    'text-[10px] font-mono transition-colors select-none',
                    isHovered ? 'fill-text-primary font-medium' : 'fill-text-muted/60'
                  )}
                >
                  {labelText}
                </text>
              )}
            </g>
          );
        })}
      </svg>
    </div>
  );
}

'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';

export type OtpInputVariant = 'default' | 'tactile' | 'recessed';
export type OtpInputSize = 'sm' | 'md' | 'lg';

export interface OtpInputProps {
  length?: number;
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  onComplete?: (value: string) => void;
  disabled?: boolean;
  autoFocus?: boolean;
  mask?: boolean;
  variant?: OtpInputVariant;
  size?: OtpInputSize;
  hasSeparator?: boolean;
  separatorIndex?: number;
  error?: boolean;
  className?: string;
  'aria-label'?: string;
}

export const OtpInput = React.forwardRef<HTMLDivElement, OtpInputProps>(
  (
    {
      length = 6,
      value: controlledValue,
      defaultValue = '',
      onChange,
      onComplete,
      disabled = false,
      autoFocus = false,
      mask = false,
      variant = 'tactile',
      size = 'md',
      hasSeparator = true,
      separatorIndex,
      error = false,
      className,
      'aria-label': ariaLabel = 'Verification Code',
    },
    ref
  ) => {
    const isControlled = controlledValue !== undefined;
    const [internalValue, setInternalValue] = React.useState<string>(defaultValue);
    const currentValue = isControlled ? controlledValue : internalValue;

    const inputRefs = React.useRef<(HTMLInputElement | null)[]>([]);
    const sepIndex = separatorIndex ?? Math.floor(length / 2);

    React.useEffect(() => {
      if (autoFocus && inputRefs.current[0]) {
        inputRefs.current[0].focus();
      }
    }, [autoFocus]);

    const digits = React.useMemo(() => {
      const arr = new Array(length).fill('');
      for (let i = 0; i < length; i++) {
        arr[i] = currentValue[i] || '';
      }
      return arr;
    }, [currentValue, length]);

    const updateValue = (newVal: string) => {
      const sanitized = newVal.slice(0, length);
      if (!isControlled) {
        setInternalValue(sanitized);
      }
      onChange?.(sanitized);
      if (sanitized.length === length) {
        onComplete?.(sanitized);
      }
    };

    const handleKeyDown = (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === 'Backspace') {
        e.preventDefault();
        const currentDigit = digits[index];
        if (currentDigit) {
          const nextVal = digits.map((d, i) => (i === index ? '' : d)).join('');
          updateValue(nextVal);
        } else if (index > 0) {
          inputRefs.current[index - 1]?.focus();
          const nextVal = digits.map((d, i) => (i === index - 1 ? '' : d)).join('');
          updateValue(nextVal);
        }
      } else if (e.key === 'ArrowLeft') {
        e.preventDefault();
        if (index > 0) {
          inputRefs.current[index - 1]?.focus();
        }
      } else if (e.key === 'ArrowRight') {
        e.preventDefault();
        if (index < length - 1) {
          inputRefs.current[index + 1]?.focus();
        }
      }
    };

    const handleChange = (index: number, e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      const char = val.slice(-1);

      if (!/^\d*$/.test(char)) {
        return;
      }

      const nextDigits = [...digits];
      nextDigits[index] = char;
      const nextVal = nextDigits.join('');
      updateValue(nextVal);

      if (char && index < length - 1) {
        inputRefs.current[index + 1]?.focus();
      }
    };

    const handlePaste = (e: React.ClipboardEvent<HTMLInputElement>) => {
      e.preventDefault();
      const pastedData = e.clipboardData.getData('text/plain').replace(/\D/g, '').slice(0, length);
      if (pastedData) {
        updateValue(pastedData);
        const focusIdx = Math.min(pastedData.length, length - 1);
        inputRefs.current[focusIdx]?.focus();
      }
    };

    const sizeClasses = {
      sm: 'w-8 h-10 text-sm font-medium rounded-lg',
      md: 'w-11 h-13 text-lg font-mono rounded-xl',
      lg: 'w-14 h-16 text-xl font-mono rounded-xl',
    };

    const variantClasses = {
      default:
        'bg-background border border-border text-foreground focus:border-foreground/50 focus:ring-1 focus:ring-ring/40',
      tactile:
        'bg-card border border-border/80 text-foreground shadow-tactile focus:border-foreground/40 focus:ring-1 focus:ring-ring/30 focus:-translate-y-0.5 transition-all duration-150',
      recessed:
        'bg-secondary/70 border border-border/60 text-foreground shadow-recessed focus:border-foreground/40 focus:ring-1 focus:ring-ring/30 transition-all duration-150',
    };

    return (
      <div
        ref={ref}
        role="group"
        aria-label={ariaLabel}
        className={cn('inline-flex items-center gap-2', className)}
      >
        {digits.map((digit, idx) => {
          const isCurrentActive =
            !disabled && (digits.findIndex((d) => d === '') === idx || (idx === length - 1 && digits[idx] !== ''));

          return (
            <React.Fragment key={idx}>
              {hasSeparator && idx === sepIndex && (
                <div
                  aria-hidden="true"
                  className="w-2.5 h-[1.5px] bg-border mx-1 self-center rounded-full opacity-60"
                />
              )}
              <input
                ref={(el) => {
                  inputRefs.current[idx] = el;
                }}
                type="text"
                inputMode="numeric"
                pattern="[0-9]*"
                maxLength={1}
                value={mask && digit ? '•' : digit}
                disabled={disabled}
                aria-label={`Digit ${idx + 1} of ${length}`}
                onChange={(e) => handleChange(idx, e)}
                onKeyDown={(e) => handleKeyDown(idx, e)}
                onPaste={handlePaste}
                onFocus={(e) => e.target.select()}
                className={cn(
                  'text-center select-none outline-none transition-all',
                  sizeClasses[size],
                  variantClasses[variant],
                  disabled && 'opacity-40 cursor-not-allowed shadow-none',
                  error && 'border-destructive/60 text-destructive focus:border-destructive focus:ring-destructive/30',
                  !digit && isCurrentActive && !disabled && 'border-foreground/30'
                )}
              />
            </React.Fragment>
          );
        })}
      </div>
    );
  }
);

OtpInput.displayName = 'OtpInput';

'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';

export interface SpotlightCardProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: 'default' | 'tactile' | 'recessed';
  spotlightSize?: number;
  spotlightColor?: string;
  ambientIntensity?: number;
}

export const SpotlightCard = React.forwardRef<HTMLDivElement, SpotlightCardProps>(
  (
    {
      className,
      children,
      variant = 'default',
      spotlightSize = 420,
      spotlightColor,
      ambientIntensity = 0.045,
      ...props
    },
    ref
  ) => {
    const cardRef = React.useRef<HTMLDivElement | null>(null);
    const [mousePos, setMousePos] = React.useState<{ x: number; y: number } | null>(null);
    const [isHovered, setIsHovered] = React.useState(false);

    const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
      if (!cardRef.current) return;
      const rect = cardRef.current.getBoundingClientRect();
      setMousePos({
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
      });
    };

    const handleMouseEnter = () => setIsHovered(true);
    const handleMouseLeave = () => {
      setIsHovered(false);
      setMousePos(null);
    };

    const variantClasses = {
      default: 'bg-card border border-border',
      tactile: 'bg-card border border-border/80 shadow-tactile',
      recessed: 'bg-secondary/70 border border-border/60 shadow-recessed',
    };

    return (
      <div
        ref={(el) => {
          cardRef.current = el;
          if (typeof ref === 'function') {
            ref(el);
          } else if (ref) {
            ref.current = el;
          }
        }}
        onMouseMove={handleMouseMove}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        className={cn(
          'relative rounded-xl p-6 overflow-hidden transition-colors duration-200',
          variantClasses[variant],
          className
        )}
        {...props}
      >
        {/* Ambient Radial Spotlight: gentle environmental condition, not decoration */}
        <div
          aria-hidden="true"
          className="pointer-events-none absolute -inset-px transition-opacity duration-500 ease-out"
          style={{
            opacity: isHovered && mousePos ? 1 : 0,
            background: mousePos
              ? `radial-gradient(${spotlightSize}px circle at ${mousePos.x}px ${mousePos.y}px, ${
                  spotlightColor || `var(--spotlight-color, rgba(255, 255, 255, ${ambientIntensity}))`
                }, transparent 70%)`
              : 'none',
          }}
        />

        {/* Content Container */}
        <div className="relative z-10">{children}</div>
      </div>
    );
  }
);

SpotlightCard.displayName = 'SpotlightCard';

