import * as React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Folder, ChevronRight, FileText, Sparkles, Layers } from 'lucide-react';
import { cn } from '@/lib/utils';
import { Badge } from '@/components/ui/badge';

export interface FolderFileItem {
  id: string;
  title: string;
  subtitle?: string;
  badge?: string;
  icon?: React.ReactNode;
  content?: React.ReactNode;
}

export interface FolderPreviewProps {
  title: string;
  category?: string;
  files: FolderFileItem[];
  defaultExpanded?: boolean;
  expanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;
  triggerMode?: 'click' | 'hover' | 'both';
  className?: string;
}

export function FolderPreview({
  title,
  category = 'ARCHIVAL BUNDLE',
  files = [],
  defaultExpanded = false,
  expanded: controlledExpanded,
  onExpandedChange,
  triggerMode = 'both',
  className,
}: FolderPreviewProps) {
  const isControlled = controlledExpanded !== undefined;
  const [internalExpanded, setInternalExpanded] = React.useState(defaultExpanded);
  const isExpanded = isControlled ? controlledExpanded : internalExpanded;

  const [activeCardIndex, setActiveCardIndex] = React.useState(0);

  const toggleExpand = () => {
    const next = !isExpanded;
    if (!isControlled) {
      setInternalExpanded(next);
    }
    onExpandedChange?.(next);
  };

  const handleMouseEnter = () => {
    if (triggerMode === 'hover' || triggerMode === 'both') {
      if (!isControlled) setInternalExpanded(true);
      onExpandedChange?.(true);
    }
  };

  const handleMouseLeave = () => {
    if (triggerMode === 'hover' || triggerMode === 'both') {
      if (!isControlled) setInternalExpanded(false);
      onExpandedChange?.(false);
    }
  };

  // Restrained rotations for the fanned stack
  const cardRotations = [-1.5, 0, 1.5, -0.75, 1];

  return (
    <div
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      className={cn('w-full max-w-md select-none', className)}
    >
      {/* Folder Container Sleeve */}
      <div
        onClick={triggerMode !== 'hover' ? toggleExpand : undefined}
        className={cn(
          'relative rounded-2xl border border-border/80 bg-card p-5 transition-all duration-300 cursor-pointer',
          'shadow-tactile hover:border-foreground/20'
        )}
      >
        {/* Top Archival Folder Tab & Metadata */}
        <div className="flex items-center justify-between pb-4 border-b border-border/60">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-lg bg-secondary/80 border border-border/60 flex items-center justify-center text-text-primary">
              <Folder className="w-4 h-4 opacity-80" />
            </div>
            <div>
              <div className="text-[10px] font-mono tracking-wider uppercase text-text-muted">
                {category}
              </div>
              <h4 className="text-sm font-medium text-text-primary tracking-tight">
                {title}
              </h4>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Badge variant="outline">
              {files.length} {files.length === 1 ? 'item' : 'items'}
            </Badge>
            <motion.div
              animate={{ rotate: isExpanded ? 90 : 0 }}
              transition={{ duration: 0.2 }}
              className="text-text-muted"
            >
              <ChevronRight className="w-4 h-4" />
            </motion.div>
          </div>
        </div>

        {/* Fanned Stack Preview Deck */}
        <div className="relative h-56 mt-4 w-full flex items-center justify-center overflow-hidden rounded-xl bg-secondary/30 border border-border/40 p-4">
          <div className="relative w-full h-full max-w-[320px]">
            {files.map((file, idx) => {
              const rotation = cardRotations[idx % cardRotations.length];
              const isTop = idx === activeCardIndex;
              const yOffset = isExpanded ? (idx - 1) * -14 : idx * 4;
              const scale = isExpanded ? 1 - idx * 0.03 : 1 - idx * 0.04;
              const zIndex = files.length - idx;

              return (
                <motion.div
                  key={file.id}
                  layout
                  onClick={(e) => {
                    e.stopPropagation();
                    setActiveCardIndex(idx);
                  }}
                  animate={{
                    y: yOffset,
                    rotate: isExpanded ? rotation : 0,
                    scale: scale,
                    opacity: 1,
                  }}
                  transition={{
                    type: 'spring',
                    stiffness: 300,
                    damping: 26,
                  }}
                  style={{ zIndex }}
                  className={cn(
                    'absolute inset-0 rounded-xl border border-border/80 bg-background p-4 shadow-tactile transition-shadow',
                    'flex flex-col justify-between cursor-pointer',
                    isTop ? 'border-foreground/30 shadow-md' : 'border-border/60 hover:border-border'
                  )}
                >
                  <div className="flex items-start justify-between">
                    <div className="flex items-center gap-2">
                      <div className="w-6 h-6 rounded-md bg-secondary/60 flex items-center justify-center text-text-muted">
                        {file.icon || <FileText className="w-3.5 h-3.5" />}
                      </div>
                      <div>
                        <div className="text-xs font-medium text-text-primary line-clamp-1">
                          {file.title}
                        </div>
                        {file.subtitle && (
                          <div className="text-[10px] text-text-muted line-clamp-1">
                            {file.subtitle}
                          </div>
                        )}
                      </div>
                    </div>
                    {file.badge && (
                      <Badge variant="secondary">
                        {file.badge}
                      </Badge>
                    )}
                  </div>

                  <div className="my-auto py-2">
                    {file.content || (
                      <div className="space-y-1.5 opacity-60">
                        <div className="h-1.5 w-3/4 rounded-full bg-secondary" />
                        <div className="h-1.5 w-1/2 rounded-full bg-secondary" />
                      </div>
                    )}
                  </div>

                  <div className="pt-2 border-t border-border/40 flex items-center justify-between text-[10px] font-mono text-text-muted">
                    <span>SHEET 0{idx + 1}</span>
                    <span className="capitalize">{isTop ? 'Active View' : 'Inspect'}</span>
                  </div>
                </motion.div>
              );
            })}
          </div>
        </div>

        {/* Quiet footer summary */}
        <div className="mt-3 flex items-center justify-between text-[11px] text-text-muted">
          <span>{isExpanded ? 'Fanned preview active' : 'Click or hover to fan stack'}</span>
          <span className="font-mono text-[10px]">ESC TO RESET</span>
        </div>
      </div>
    </div>
  );
}

'use client';

import * as React from 'react';
import { motion } from 'framer-motion';
import { cn } from '@/lib/utils';

export interface MagneticTabItem {
  id: string;
  label: string;
  icon?: React.ReactNode;
  badge?: string | number;
  disabled?: boolean;
}

export interface MagneticTabsProps {
  tabs: MagneticTabItem[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  variant?: 'default' | 'tactile' | 'recessed';
  size?: 'sm' | 'md' | 'lg';
  className?: string;
}

export function MagneticTabs({
  tabs,
  value: controlledValue,
  defaultValue,
  onValueChange,
  variant = 'tactile',
  size = 'md',
  className,
}: MagneticTabsProps) {
  const isControlled = controlledValue !== undefined;
  const [internalValue, setInternalValue] = React.useState<string>(
    defaultValue || (tabs[0] ? tabs[0].id : '')
  );
  const activeValue = isControlled ? controlledValue : internalValue;

  const handleSelect = (tabId: string, disabled?: boolean) => {
    if (disabled) return;
    if (!isControlled) {
      setInternalValue(tabId);
    }
    onValueChange?.(tabId);
  };

  const handleKeyDown = (e: React.KeyboardEvent, currentIndex: number) => {
    let nextIndex = -1;
    if (e.key === 'ArrowRight') {
      nextIndex = (currentIndex + 1) % tabs.length;
    } else if (e.key === 'ArrowLeft') {
      nextIndex = (currentIndex - 1 + tabs.length) % tabs.length;
    } else if (e.key === 'Home') {
      nextIndex = 0;
    } else if (e.key === 'End') {
      nextIndex = tabs.length - 1;
    }

    if (nextIndex !== -1) {
      e.preventDefault();
      const targetTab = tabs[nextIndex];
      if (targetTab && !targetTab.disabled) {
        handleSelect(targetTab.id);
      }
    }
  };

  const sizeStyles = {
    sm: {
      container: 'p-0.5 gap-0.5 rounded-lg text-xs',
      tab: 'px-2.5 py-1 rounded-md text-xs gap-1.5',
    },
    md: {
      container: 'p-1 gap-1 rounded-xl text-sm',
      tab: 'px-3.5 py-1.5 rounded-lg text-sm gap-2',
    },
    lg: {
      container: 'p-1.5 gap-1.5 rounded-xl text-base',
      tab: 'px-4.5 py-2 rounded-lg text-base gap-2.5',
    },
  };

  const containerVariants = {
    default: 'bg-secondary/60 border border-border/80',
    tactile: 'bg-card border border-border/80 shadow-tactile',
    recessed: 'bg-secondary/70 border border-border/60 shadow-recessed',
  };

  const pillVariants = {
    default: 'bg-background shadow-xs border border-border/60',
    tactile: 'bg-background shadow-tactile border border-border/70',
    recessed: 'bg-card shadow-xs border border-border/50',
  };

  const uniqueLayoutId = React.useId();

  return (
    <div
      role="tablist"
      aria-orientation="horizontal"
      className={cn(
        'inline-flex items-center select-none',
        containerVariants[variant],
        sizeStyles[size].container,
        className
      )}
    >
      {tabs.map((tab, idx) => {
        const isActive = tab.id === activeValue;

        return (
          <button
            key={tab.id}
            role="tab"
            type="button"
            aria-selected={isActive}
            aria-controls={`panel-${tab.id}`}
            id={`tab-${tab.id}`}
            tabIndex={isActive ? 0 : -1}
            disabled={tab.disabled}
            onClick={() => handleSelect(tab.id, tab.disabled)}
            onKeyDown={(e) => handleKeyDown(e, idx)}
            className={cn(
              'relative inline-flex items-center justify-center font-medium transition-colors outline-none cursor-pointer',
              sizeStyles[size].tab,
              isActive ? 'text-text-primary' : 'text-text-muted hover:text-text-secondary',
              tab.disabled && 'opacity-40 cursor-not-allowed hover:text-text-muted'
            )}
          >
            {/* Magnetic Active Sliding Indicator Pill */}
            {isActive && (
              <motion.div
                layoutId={`magnetic-pill-${uniqueLayoutId}`}
                className={cn('absolute inset-0 z-0', pillVariants[variant], sizeStyles[size].tab.includes('rounded-md') ? 'rounded-md' : 'rounded-lg')}
                transition={{
                  type: 'spring',
                  stiffness: 380,
                  damping: 30,
                }}
              />
            )}

            {/* Tab Label Content */}
            <span className="relative z-10 inline-flex items-center gap-1.5">
              {tab.icon && (
                <span className={cn('shrink-0 transition-opacity', isActive ? 'opacity-100' : 'opacity-70')}>
                  {tab.icon}
                </span>
              )}
              <span>{tab.label}</span>
              {tab.badge !== undefined && (
                <span
                  className={cn(
                    'text-[10px] px-1.5 py-0.5 rounded-full font-mono font-medium transition-colors',
                    isActive
                      ? 'bg-secondary text-text-primary'
                      : 'bg-background/80 text-text-muted'
                  )}
                >
                  {tab.badge}
                </span>
              )}
            </span>
          </button>
        );
      })}
    </div>
  );
}

'use client';

import * as React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronLeft, ChevronRight, Layers } from 'lucide-react';
import { cn } from '@/lib/utils';
import { IconButton } from '@/components/ui/icon-button';
import { Badge } from '@/components/ui/badge';

export interface StackCardItem {
  id: string;
  title: string;
  tag?: string;
  description?: string;
  content?: React.ReactNode;
}

export interface StackDeckProps {
  cards: StackCardItem[];
  currentIndex?: number;
  onIndexChange?: (index: number) => void;
  variant?: 'default' | 'tactile' | 'recessed';
  className?: string;
}

export function StackDeck({
  cards,
  currentIndex: controlledIndex,
  onIndexChange,
  variant = 'tactile',
  className,
}: StackDeckProps) {
  const isControlled = controlledIndex !== undefined;
  const [internalIndex, setInternalIndex] = React.useState(0);
  const activeIndex = isControlled ? controlledIndex : internalIndex;

  const handleNext = () => {
    if (cards.length <= 1) return;
    const next = (activeIndex + 1) % cards.length;
    if (!isControlled) setInternalIndex(next);
    onIndexChange?.(next);
  };

  const handlePrev = () => {
    if (cards.length <= 1) return;
    const prev = (activeIndex - 1 + cards.length) % cards.length;
    if (!isControlled) setInternalIndex(prev);
    onIndexChange?.(prev);
  };

  const variantClasses = {
    default: 'bg-card border border-border',
    tactile: 'bg-card border border-border/80 shadow-tactile',
    recessed: 'bg-secondary/70 border border-border/60 shadow-recessed',
  };

  // Render max 3 cards visually stacked
  const visibleCardsCount = Math.min(3, cards.length);
  const reorderedCards = [];
  for (let i = 0; i < visibleCardsCount; i++) {
    const idx = (activeIndex + i) % cards.length;
    reorderedCards.push({ ...cards[idx], stackIndex: i });
  }

  return (
    <div className={cn('w-full max-w-md select-none', className)}>
      {/* Stack Viewport Area */}
      <div className="relative h-64 w-full flex items-center justify-center">
        {reorderedCards
          .slice()
          .reverse()
          .map((card) => {
            const isTop = card.stackIndex === 0;
            const yOffset = card.stackIndex * 12;
            const scale = 1 - card.stackIndex * 0.05;
            const opacity = 1 - card.stackIndex * 0.22;
            const zIndex = visibleCardsCount - card.stackIndex;

            return (
              <motion.div
                key={card.id}
                layout
                initial={false}
                animate={{
                  y: yOffset,
                  scale,
                  opacity,
                }}
                transition={{
                  type: 'spring',
                  stiffness: 320,
                  damping: 28,
                }}
                style={{ zIndex }}
                onClick={!isTop ? handleNext : undefined}
                className={cn(
                  'absolute inset-x-0 top-2 h-52 rounded-2xl p-5 flex flex-col justify-between transition-colors',
                  variantClasses[variant],
                  !isTop && 'cursor-pointer hover:border-foreground/30'
                )}
              >
                <div>
                  <div className="flex items-center justify-between gap-2 mb-2">
                    <div className="flex items-center gap-2">
                      <Layers className="w-4 h-4 text-text-muted" />
                      <span className="text-[11px] font-mono uppercase text-text-muted">
                        Index {card.id}
                      </span>
                    </div>
                    {card.tag && (
                      <Badge variant="secondary">
                        {card.tag}
                      </Badge>
                    )}
                  </div>
                  <h4 className="text-base font-medium text-text-primary tracking-tight">
                    {card.title}
                  </h4>
                  {card.description && (
                    <p className="mt-1 text-xs text-text-muted leading-relaxed line-clamp-2">
                      {card.description}
                    </p>
                  )}
                </div>

                {card.content && <div className="my-auto py-1">{card.content}</div>}

                <div className="pt-3 border-t border-border/60 flex items-center justify-between text-[11px] font-mono text-text-muted">
                  <span>
                    0{activeIndex + 1} / 0{cards.length}
                  </span>
                  <span>{isTop ? 'Current View' : 'Click to bring forward'}</span>
                </div>
              </motion.div>
            );
          })}
      </div>

      {/* Deck Controls */}
      <div className="mt-3 flex items-center justify-between px-2">
        <div className="flex items-center gap-1.5">
          {cards.map((c, i) => (
            <button
              key={c.id}
              type="button"
              aria-label={`Jump to slide ${i + 1}`}
              onClick={() => {
                if (!isControlled) setInternalIndex(i);
                onIndexChange?.(i);
              }}
              className={cn(
                'h-1.5 rounded-full transition-all duration-200 cursor-pointer',
                i === activeIndex
                  ? 'w-6 bg-foreground'
                  : 'w-1.5 bg-border hover:bg-text-muted'
              )}
            />
          ))}
        </div>

        <div className="flex items-center gap-1.5">
          <IconButton
            icon={<ChevronLeft className="w-4 h-4" />}
            aria-label="Previous card"
            variant="ghost"
            size="sm"
            onClick={handlePrev}
          />
          <IconButton
            icon={<ChevronRight className="w-4 h-4" />}
            aria-label="Next card"
            variant="ghost"
            size="sm"
            onClick={handleNext}
          />
        </div>
      </div>
    </div>
  );
}

