                              ? isHovered
                                ? 'bg-text-primary scale-125 shadow-[0_0_8px_rgba(var(--foreground-rgb),0.2)]'
                                : 'bg-text-primary/85'
                              : isHovered
                              ? 'bg-text-muted scale-115'
                              : 'bg-text-muted/50'
                            : 'bg-foreground/[0.04] dark:bg-foreground/[0.08] border border-border/20'
