import * as React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '@/lib/utils';

export interface CandleDataPoint {
  time: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

export interface CandlestickChartProps extends React.HTMLAttributes<HTMLDivElement> {
  data: CandleDataPoint[];
  height?: number;
  showVolume?: boolean;
  showAxes?: boolean;
  unit?: string;
}

export function CandlestickChart({
  data,
  height = 280,
  showVolume = true,
  showAxes = true,
  unit = '$',
  className,
  ...props
}: CandlestickChartProps) {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const [width, setWidth] = React.useState(600);
  const [hoveredIndex, setHoveredIndex] = React.useState<number | null>(null);

  React.useEffect(() => {
    if (!containerRef.current) return;
    const observer = new ResizeObserver((entries) => {
      if (entries[0]) {
        setWidth(entries[0].contentRect.width);
      }
    });
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  if (!data || data.length === 0) {
    return (
      <div
        ref={containerRef}
        style={{ height }}
        className="w-full flex items-center justify-center rounded-[24px] bg-card border border-border/60 text-xs font-mono text-text-muted"
      >
        No market data available
      </div>
    );
  }

  const paddingLeft = showAxes ? 52 : 16;
  const paddingRight = 20;
  const paddingTop = 28;
  const paddingBottom = showAxes ? 32 : 16;

  const chartWidth = Math.max(10, width - paddingLeft - paddingRight);
  const totalHeight = Math.max(10, height - paddingTop - paddingBottom);
  const volumeHeight = showVolume ? totalHeight * 0.22 : 0;
  const candleAreaHeight = totalHeight - volumeHeight - (showVolume ? 12 : 0);

  // Calculate Price Range
  const allHighs = data.map((d) => d.high);
  const allLows = data.map((d) => d.low);
  const minPrice = Math.min(...allLows) * 0.998;
  const maxPrice = Math.max(...allHighs) * 1.002;
  const priceRange = maxPrice - minPrice || 1;

  // Calculate Volume Range
  const maxVolume = Math.max(...data.map((d) => d.volume), 1);

  const slotWidth = chartWidth / data.length;
  const candleWidth = Math.min(18, Math.max(6, slotWidth * 0.55));

  const hoveredCandle = hoveredIndex !== null ? data[hoveredIndex] : null;

  return (
    <div
      ref={containerRef}
      className={cn(
        'relative w-full rounded-[24px] border border-border/70 bg-card select-none shadow-tactile transition-colors overflow-hidden',
        className
      )}
      style={{ height }}
      onMouseLeave={() => setHoveredIndex(null)}
      {...props}
    >
      {/* Precision Floating Telemetry Pill */}
      <div className="absolute top-3 right-4 z-20 flex items-center gap-3 text-xs font-mono pointer-events-none">
        {hoveredCandle ? (
          <div className="px-3 py-1 rounded-xl bg-card/95 backdrop-blur-md border border-border/90 text-[11px] font-mono shadow-tactile flex items-center gap-3">
            <span className="text-text-muted">{hoveredCandle.time}</span>
            <span>O: <strong className="text-text-primary">{unit}{hoveredCandle.open.toFixed(2)}</strong></span>
            <span>H: <strong className="text-emerald-500">{unit}{hoveredCandle.high.toFixed(2)}</strong></span>
            <span>L: <strong className="text-rose-500">{unit}{hoveredCandle.low.toFixed(2)}</strong></span>
            <span>C: <strong className={hoveredCandle.close >= hoveredCandle.open ? 'text-emerald-500' : 'text-rose-500'}>{unit}{hoveredCandle.close.toFixed(2)}</strong></span>
            {showVolume && <span className="text-text-muted">Vol: {hoveredCandle.volume.toLocaleString()}</span>}
          </div>
        ) : (
          <span className="text-[10px] font-mono text-text-muted/60">Hover candle to inspect OHLC</span>
        )}
      </div>

      <svg width={width} height={height} className="overflow-visible block">
        {/* Horizontal Price Gridlines */}
        {[0, 0.5, 1].map((tier, idx) => {
          const y = paddingTop + candleAreaHeight * (1 - tier);
          const price = minPrice + tier * priceRange;
          return (
            <g key={idx}>
              <line
                x1={paddingLeft}
                y1={y}
                x2={chartWidth + paddingLeft}
                y2={y}
                stroke="var(--border)"
                strokeDasharray="3 3"
                strokeWidth="0.75"
                className="opacity-50"
              />
              {showAxes && (
                <text
                  x={paddingLeft - 10}
                  y={y + 3.5}
                  textAnchor="end"
                  className="text-[10px] font-mono fill-text-muted/60 select-none"
                >
                  {unit}{price.toFixed(2)}
                </text>
              )}
            </g>
          );
        })}

        {/* Candlestick Glyphs & Volume Bars */}
        {data.map((d, idx) => {
          const isBullish = d.close >= d.open;
          const candleColor = isBullish ? '#10b981' : '#f43f5e';
          const centerX = paddingLeft + idx * slotWidth + slotWidth / 2;
          const leftX = centerX - candleWidth / 2;

          const highY = paddingTop + candleAreaHeight - ((d.high - minPrice) / priceRange) * candleAreaHeight;
          const lowY = paddingTop + candleAreaHeight - ((d.low - minPrice) / priceRange) * candleAreaHeight;
          const openY = paddingTop + candleAreaHeight - ((d.open - minPrice) / priceRange) * candleAreaHeight;
          const closeY = paddingTop + candleAreaHeight - ((d.close - minPrice) / priceRange) * candleAreaHeight;

          const bodyY = Math.min(openY, closeY);
          const bodyHeight = Math.max(2, Math.abs(closeY - openY));

          // Volume Bar Coordinates
          const volBarHeight = showVolume ? (d.volume / maxVolume) * volumeHeight : 0;
          const volY = paddingTop + totalHeight - volBarHeight;

          const isHovered = hoveredIndex === idx;

          return (
            <g key={idx}>
              {/* Vertical Scrubber Highlight */}
              {isHovered && (
                <line
                  x1={centerX}
                  y1={paddingTop}
                  x2={centerX}
                  y2={paddingTop + totalHeight}
                  stroke="var(--border)"
                  strokeDasharray="2 2"
                  strokeWidth="1"
                  className="opacity-80"
                />
              )}

              {/* High-Low Wick Line */}
              <line
                x1={centerX}
                y1={highY}
                x2={centerX}
                y2={lowY}
                stroke={candleColor}
                strokeWidth="1.25"
                className="opacity-80 pointer-events-none"
              />

              {/* Open-Close Candle Body */}
              <rect
                x={leftX}
                y={bodyY}
                width={candleWidth}
                height={bodyHeight}
                rx={2.5}
                fill={candleColor}
                className={cn(
                  'transition-all duration-150 pointer-events-none drop-shadow-2xs',
                  isHovered ? 'brightness-125' : 'opacity-90'
                )}
              />

              {/* Volume Bar */}
              {showVolume && (
                <rect
                  x={leftX}
                  y={volY}
                  width={candleWidth}
                  height={volBarHeight}
                  rx={2}
                  fill={candleColor}
                  className={cn(
                    'transition-all duration-150 pointer-events-none',
                    isHovered ? 'opacity-80' : 'opacity-35'
                  )}
                />
              )}

              {/* Interactive Hit Area */}
              <rect
                x={paddingLeft + idx * slotWidth}
                y={0}
                width={slotWidth}
                height={height}
                fill="transparent"
                className="cursor-pointer"
                onMouseEnter={() => setHoveredIndex(idx)}
              />

              {/* Time Label on X-Axis */}
              {showAxes && idx % Math.ceil(data.length / 6) === 0 && (
                <text
                  x={centerX}
                  y={paddingTop + totalHeight + 20}
                  textAnchor="middle"
                  className="text-[10px] font-mono fill-text-muted/60 select-none"
                >
                  {d.time}
                </text>
              )}
            </g>
          );
        })}
      </svg>
    </div>
  );
}

'use client';

import * as React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '@/lib/utils';
import { ChevronRight, Activity, Clock, Cpu } from 'lucide-react';

export type ChurningPattern = 'wavefront' | 'dots' | 'orbit' | 'pulse' | 'matrix';
export type ChurningVariant = 'tactile' | 'recessed' | 'minimal';

export interface TelemetryMetric {
  label: string;
  value: string | number;
}

export interface AiChurningProps extends React.HTMLAttributes<HTMLDivElement> {
  label?: string;
  sublabel?: string;
  variant?: ChurningVariant;
  pattern?: ChurningPattern;
  gridSize?: 3 | 4;
  showTimer?: boolean;
  showTelemetry?: boolean;
  telemetry?: TelemetryMetric[];
  isPaused?: boolean;
}

/* ─────────────────────────────────────────────────────────
 * Matrix Pattern Precomputations
 * ───────────────────────────────────────────────────────── */
// 3x3 Chevron wavefront
const CHEVRON_3X3 = Array.from({ length: 9 }, (_, i) => {
  const r = Math.floor(i / 3);
  const c = i % 3;
  return (c + Math.abs(r - 1)) * 90;
});

// 3x3 Orbit perimeter
const ORBIT_3X3_ORDER = [0, 1, 2, 5, 8, 7, 6, 3];
const ORBIT_3X3 = Array.from({ length: 9 }, (_, i) => {
  const k = ORBIT_3X3_ORDER.indexOf(i);
  return k === -1 ? null : k * 110;
});

// 3x3 Radial pulse from center (index 4)
const PULSE_3X3 = [200, 100, 200, 100, 0, 100, 200, 100, 200];

// 4x4 Chevron wavefront
const CHEVRON_4X4 = Array.from({ length: 16 }, (_, i) => {
  const r = Math.floor(i / 4);
  const c = i % 4;
  return (c + Math.abs(r - 1.5)) * 75;
});

// 4x4 Orbit perimeter
const ORBIT_4X4_ORDER = [0, 1, 2, 3, 7, 11, 15, 14, 13, 12, 8, 4];
const ORBIT_4X4 = Array.from({ length: 16 }, (_, i) => {
  const k = ORBIT_4X4_ORDER.indexOf(i);
  return k === -1 ? null : k * 85;
});

// 4x4 Radial pulse from center 4 cells
const PULSE_4X4 = [
  240, 150, 150, 240,
  150, 0, 0, 150,
  150, 0, 0, 150,
  240, 150, 150, 240
];

function useElapsedTimer(isPaused = false) {
  const [ds, setDs] = React.useState(0);

  React.useEffect(() => {
    if (isPaused) return;
    const interval = setInterval(() => {
      setDs((prev) => prev + 1);
    }, 100);
    return () => clearInterval(interval);
  }, [isPaused]);

  const totalSec = ds / 10;
  if (totalSec < 60) {
    return `${totalSec.toFixed(1)}s`;
  }
  const mins = Math.floor(totalSec / 60);
  const secs = (totalSec % 60).toFixed(1);
  return `${mins}m ${secs}s`;
}

export function AiChurning({
  label = 'Churning',
  sublabel,
  variant = 'tactile',
  pattern = 'wavefront',
  gridSize = 3,
  showTimer = true,
  showTelemetry = false,
  telemetry = [
    { label: 'Tokens/s', value: '48.2' },
    { label: 'KV Cache', value: '82%' },
    { label: 'Latency', value: '18ms' },
  ],
  isPaused = false,
  className,
  ...props
}: AiChurningProps) {
  const elapsed = useElapsedTimer(isPaused);
  const [telemetryOpen, setTelemetryOpen] = React.useState(false);

  // Determine grid cells delay map
  const totalCells = gridSize === 4 ? 16 : 9;
  const isRound = pattern === 'dots';

  const delays = React.useMemo(() => {
    if (gridSize === 4) {
      if (pattern === 'orbit') return ORBIT_4X4;
      if (pattern === 'pulse') return PULSE_4X4;
      if (pattern === 'matrix') {
        return Array.from({ length: 16 }, (_, i) => (Math.sin(i * 37) * 400 + 400) % 700);
      }
      return CHEVRON_4X4;
    } else {
      if (pattern === 'orbit') return ORBIT_3X3;
      if (pattern === 'pulse') return PULSE_3X3;
      if (pattern === 'matrix') {
        return Array.from({ length: 9 }, (_, i) => (Math.sin(i * 43) * 350 + 350) % 650);
      }
      return CHEVRON_3X3;
    }
  }, [gridSize, pattern]);

  const cycleDuration = pattern === 'orbit' ? 950 : 680;

  // Grid styling
  const gridColsClass = gridSize === 4 ? 'grid-cols-[repeat(4,4.5px)]' : 'grid-cols-[repeat(3,4.5px)]';

  const variantContainerClasses = {
    minimal: 'bg-transparent border-none p-0',
    tactile: 'bg-card border border-border/80 shadow-tactile rounded-2xl px-4 py-3.5',
    recessed: 'bg-secondary/40 border border-border/60 shadow-inner-tactile rounded-2xl px-4 py-3.5',
  };

  return (
    <div
      role="status"
      aria-label={`${label} ${showTimer ? elapsed : ''}`}
      className={cn('inline-flex flex-col select-none transition-all', variantContainerClasses[variant], className)}
      {...props}
    >
      <div className="flex items-center gap-3">
        {/* Phosphor Pixel Grid Well */}
        <div className="relative p-1.5 rounded-lg bg-secondary/50 border border-border/50 flex items-center justify-center shrink-0">
          <div
            aria-hidden="true"
            className={cn('grid gap-[2px]', gridColsClass)}
          >
            {delays.map((delay, index) => {
              const isInactive = delay === null;
              return (
                <span
                  key={index}
                  className={cn(
                    'w-[4.5px] h-[4.5px] bg-foreground transition-opacity',
                    isRound ? 'rounded-full' : 'rounded-[1px]'
                  )}
                  style={{
                    opacity: isInactive ? 0.08 : 0.2,
                    animation:
                      isInactive || isPaused
                        ? 'none'
                        : `ai-cell-glow ${cycleDuration}ms cubic-bezier(0.4, 0, 0.2, 1) ${delay}ms infinite`,
                  }}
                />
              );
            })}
          </div>
        </div>

        {/* Shimmering Phase Label */}
        <div className="flex flex-col min-w-0">
          <div className="flex items-center gap-2">
            <span
              className="text-[13px] font-medium tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-text-muted via-foreground to-text-muted bg-[length:200%_100%]"
              style={{
                animation: isPaused ? 'none' : 'ai-shimmer 1.8s linear infinite',
              }}
            >
              {label}
            </span>

            {/* Live Tabular Timer */}
            {showTimer && (
              <span className="font-mono text-[11px] tabular-nums text-text-muted bg-secondary/40 px-1.5 py-0.5 rounded border border-border/40">
                {elapsed}
              </span>
            )}
          </div>

          {sublabel && (
            <span className="text-[11px] text-text-muted/80 font-mono tracking-tight line-clamp-1">
              {sublabel}
            </span>
          )}
        </div>

        {/* Telemetry Expand Toggle */}
        {showTelemetry && (
          <button
            type="button"
            onClick={() => setTelemetryOpen(!telemetryOpen)}
            aria-label="Toggle telemetry details"
            className="ml-auto pl-2 text-text-muted hover:text-text-primary p-1 rounded transition-colors cursor-pointer"
